function validate([a, b]) {
  if (!Number.isInteger(a) || a < 1 || a > 1000) return 'a is an integer from 1 to 1000.';
  if (!Number.isInteger(b) || b < 1 || b > 1000) return 'b is an integer from 1 to 1000.';
  return null;
}

