function commonFactors(a, b) {
  let gcd = a;
  let rest = b;
  while (rest !== 0) {
    const remainder = gcd % rest;
    gcd = rest;
    rest = remainder;
  }

  let count = 0;
  for (let d = 1; d * d <= gcd; d++) {
    if (gcd % d === 0) {
      count += d * d === gcd ? 1 : 2;
    }
  }
  return count;
}

