function generate(rand, size) {
  const limit = size === 'large' ? 1000 : 60;
  if (rand() < 0.5) {
    return [1 + Math.floor(rand() * limit), 1 + Math.floor(rand() * limit)];
  }
  // Build both numbers from a shared factor so that larger answers show up often.
  const shared = 1 + Math.floor(rand() * Math.floor(limit / 2));
  const most = Math.floor(limit / shared);
  return [shared * (1 + Math.floor(rand() * most)), shared * (1 + Math.floor(rand() * most))];
}
